import{_ as e,o as i,c as o,a3 as n}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Signing in with Microsoft","description":"Clearing ApptiveGrid as an enterprise application in Microsoft Entra — for users and IT administrators.","frontmatter":{"title":"Signing in with Microsoft","description":"Clearing ApptiveGrid as an enterprise application in Microsoft Entra — for users and IT administrators."},"headers":[],"relativePath":"en/erste-schritte/anmeldung-mit-microsoft.md","filePath":"en/erste-schritte/anmeldung-mit-microsoft.md","lastUpdated":1787814657000}'),a={name:"en/erste-schritte/anmeldung-mit-microsoft.md"};function r(s,t,d,p,c,l){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="signing-in-with-microsoft" tabindex="-1">Signing in with Microsoft <a class="header-anchor" href="#signing-in-with-microsoft" aria-label="Permalink to &quot;Signing in with Microsoft&quot;">​</a></h1><p>ApptiveGrid can be used with an existing Microsoft account — through the <strong>Continue with Microsoft</strong> button on the login page. No separate password is set.</p><p>For <strong>work and school accounts</strong>, your own organization&#39;s IT decides which external applications may sign people in. If that is restricted, sign-in may stop with <em>Approval required</em>. Nothing is wrong with your account — an approval is missing in <strong>Microsoft Entra</strong>.</p><div class="tip custom-block"><p class="custom-block-title">This page is meant to be passed on</p><p>You can send it to your IT department as it is. The second part holds everything they need for the decision: the permissions requested, the application ID, and the path through the Microsoft Entra portal.</p></div><h2 id="for-users" tabindex="-1">For users <a class="header-anchor" href="#for-users" aria-label="Permalink to &quot;For users&quot;">​</a></h2><ol><li>Open <a href="https://app.apptivegrid.de" target="_blank" rel="noreferrer">app.apptivegrid.de</a> and choose <strong>Continue with Microsoft</strong>.</li><li>If <em>Approval required</em> appears and your organization offers it, you can send the request straight from that dialog with a justification.</li><li>If the dialog doesn&#39;t offer that, contact your IT department and pass this page along.</li></ol><p>Once the approval is granted, other people in your organization can sign in as well, in principle. Your IT can additionally limit access to specific users or groups; if <em>Assignment required</em> is switched on in Microsoft Entra, sign-in works only for the people assigned there.</p><p>If instead you get <em>Sorry, but we&#39;re having trouble signing you in</em> with a code like <code>AADSTS7000112</code>, ApptiveGrid is explicitly blocked in your organization. That, too, can only be lifted there — pass this page along as well.</p><div class="warning custom-block"><p class="custom-block-title">Always take the same route</p><p>An account created through Microsoft has no password of its own at ApptiveGrid. Always sign in using that same button. → <a href="/en/erste-schritte/konto-und-anmeldung">Account and sign-in</a></p></div><hr><h2 id="for-it-administrators" tabindex="-1">For IT administrators <a class="header-anchor" href="#for-it-administrators" aria-label="Permalink to &quot;For IT administrators&quot;">​</a></h2><p>ApptiveGrid is an application for capturing, analyzing, and sharing structured data (operated by ApptiveGrid GmbH). For sign-in, it uses Microsoft Entra ID as the identity provider, via standard OpenID Connect.</p><p><strong>The Microsoft password is never passed to ApptiveGrid.</strong> Sign-in happens entirely at Microsoft. What comes back are the OpenID Connect claims needed to identify the user: a user identifier, the name, and — where it is held in Microsoft Entra — the email address.</p><h3 id="what-is-requested" tabindex="-1">What is requested <a class="header-anchor" href="#what-is-requested" aria-label="Permalink to &quot;What is requested&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Application (client) ID</td><td><code>c5bf8ba8-b06b-4d90-a16b-3598f50d9950</code></td></tr><tr><td>Permissions</td><td><code>openid</code>, <code>profile</code>, <code>email</code></td></tr><tr><td>Redirect URI</td><td><code>https://app.apptivegrid.de/auth/callback/microsoft</code></td></tr><tr><td>Protocol</td><td>OpenID Connect, authorization code</td></tr></tbody></table><p>These are the three standard scopes for sign-in only:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Meaning</th></tr></thead><tbody><tr><td><code>openid</code></td><td>Identify and sign in the user securely</td></tr><tr><td><code>profile</code></td><td>Basic profile information about the signed-in user</td></tr><tr><td><code>email</code></td><td>Email address, where available from Microsoft</td></tr></tbody></table><p>This gives ApptiveGrid no access to mailboxes, files, calendars, or Teams, and no way to read or change Microsoft 365 data through Microsoft Graph.</p><h3 id="which-message-is-it" tabindex="-1">Which message is it <a class="header-anchor" href="#which-message-is-it" aria-label="Permalink to &quot;Which message is it&quot;">​</a></h3><p>There are three distinct cases, and they call for three different fixes:</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><em>Approval required</em> — <code>AADSTS90094</code></td><td>Administrator consent is missing</td><td>Routes 1 to 3</td></tr><tr><td><em>Application &#39;…&#39; (ApptiveGrid) is disabled</em> — <code>AADSTS7000112</code></td><td>The entry exists, but sign-in is turned off for it</td><td><a href="#re-enabling-a-disabled-application">Re-enabling a disabled application</a></td></tr><tr><td><em>… is not assigned to a role for the application</em> — <code>AADSTS50105</code></td><td><em>Assignment required</em> is set to <strong>Yes</strong>, but the person isn&#39;t assigned</td><td><a href="#limiting-it-to-certain-people">Limiting it to certain people</a></td></tr></tbody></table><h3 id="why-consent-is-missing" tabindex="-1">Why consent is missing <a class="header-anchor" href="#why-consent-is-missing" aria-label="Permalink to &quot;Why consent is missing&quot;">​</a></h3><p>In many organizations, user consent for external applications is restricted or switched off entirely — the setting sits under <em>Enterprise applications</em> → <strong>Consent and permissions</strong>. Administrator consent for ApptiveGrid may then be required. In the sign-in logs, this usually shows up as <code>AADSTS90094</code>.</p><h3 id="route-1-·-approve-the-pending-request" tabindex="-1">Route 1 · Approve the pending request <a class="header-anchor" href="#route-1-·-approve-the-pending-request" aria-label="Permalink to &quot;Route 1 · Approve the pending request&quot;">​</a></h3><p>If someone submitted the request from the sign-in dialog, it&#39;s waiting in the <a href="https://entra.microsoft.com" target="_blank" rel="noreferrer">Microsoft Entra admin center</a> under <strong>Identity</strong> → <strong>Applications</strong> → <strong>Enterprise applications</strong> → <em>Admin consent requests</em>.</p><h3 id="route-2-·-grant-consent-directly" tabindex="-1">Route 2 · Grant consent directly <a class="header-anchor" href="#route-2-·-grant-consent-directly" aria-label="Permalink to &quot;Route 2 · Grant consent directly&quot;">​</a></h3><p><strong>Enterprise applications</strong> → <strong>ApptiveGrid</strong> → <em>Permissions</em> → <strong>Grant admin consent for {organization}</strong>.</p><h3 id="route-3-·-if-apptivegrid-isn-t-in-the-directory-yet" tabindex="-1">Route 3 · If ApptiveGrid isn&#39;t in the directory yet <a class="header-anchor" href="#route-3-·-if-apptivegrid-isn-t-in-the-directory-yet" aria-label="Permalink to &quot;Route 3 · If ApptiveGrid isn&#39;t in the directory yet&quot;">​</a></h3><p>If nobody has tried yet, there&#39;s no entry either. This call creates it and grants consent in one step — <code>&lt;tenant&gt;</code> being the tenant ID or the domain name:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://login.microsoftonline.com/&lt;tenant&gt;/adminconsent?client_id=c5bf8ba8-b06b-4d90-a16b-3598f50d9950</span></span></code></pre></div><h3 id="re-enabling-a-disabled-application" tabindex="-1">Re-enabling a disabled application <a class="header-anchor" href="#re-enabling-a-disabled-application" aria-label="Permalink to &quot;Re-enabling a disabled application&quot;">​</a></h3><blockquote><p><em>AADSTS7000112: Application &#39;c5bf8ba8-b06b-4d90-a16b-3598f50d9950&#39; (ApptiveGrid) is disabled.</em></p></blockquote><p>Nothing is missing here in terms of consent. ApptiveGrid is already in the directory, but sign-in is switched off for that entry. The switch:</p><p><strong>Enterprise applications</strong> → <strong>ApptiveGrid</strong> → <em>Properties</em> → <strong>Enabled for users to sign-in?</strong> to <strong>Yes</strong>.</p><div class="warning custom-block"><p class="custom-block-title">The block is a decision, not a fault</p><p>That switch doesn&#39;t move to <em>No</em> on its own. Check within your team whether the application was blocked deliberately — under an app governance policy, for instance — before you flip it back.</p></div><p>The block applies only within your own tenant. To users it looks like an outage at ApptiveGrid, even though nothing has changed outside the organization.</p><h3 id="limiting-it-to-certain-people" tabindex="-1">Limiting it to certain people <a class="header-anchor" href="#limiting-it-to-certain-people" aria-label="Permalink to &quot;Limiting it to certain people&quot;">​</a></h3><p>Consent initially applies to the whole organization. If only part of the workforce should use ApptiveGrid:</p><p><strong>Enterprise applications</strong> → <strong>ApptiveGrid</strong> → <em>Properties</em> → <strong>Assignment required?</strong> to <strong>Yes</strong>. Then assign the intended people or groups under <em>Users and groups</em>.</p><h3 id="revoking" tabindex="-1">Revoking <a class="header-anchor" href="#revoking" aria-label="Permalink to &quot;Revoking&quot;">​</a></h3><p><strong>Enterprise applications</strong> → <strong>ApptiveGrid</strong> → <em>Properties</em> → <strong>Delete</strong>. Sign-in through Microsoft is blocked again immediately.</p><div class="tip custom-block"><p class="custom-block-title">There are no costs on the Microsoft side</p><p>The clearance is a consent, not a license. ApptiveGrid&#39;s own plan is booked per Space, independently of this. → <a href="/en/zusammenarbeit/sitzplaetze">Seats</a></p></div><h3 id="provisioning-users-automatically-scim" tabindex="-1">Provisioning users automatically (SCIM) <a class="header-anchor" href="#provisioning-users-automatically-scim" aria-label="Permalink to &quot;Provisioning users automatically (SCIM)&quot;">​</a></h3><p>Beyond sign-in, ApptiveGrid supports <strong>SCIM</strong>: Microsoft Entra creates the user accounts in ApptiveGrid itself and keeps them current. The set of accounts then follows the organization&#39;s directory instead of being maintained by hand.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Identity provider</td><td>Microsoft Entra ID</td></tr><tr><td>What is transferred</td><td>Users and groups</td></tr><tr><td>Available on</td><td>the Enterprise plan</td></tr></tbody></table><p>Setup happens together with us. Enquiries to <strong><a href="mailto:support@apptivegrid.de" target="_blank" rel="noreferrer">support@apptivegrid.de</a></strong>.</p><div class="tip custom-block"><p class="custom-block-title">Groups are not yet a permission</p><p>Organization groups that come across are shown on the person&#39;s profile. Access to a Space is still granted through <a href="/en/zusammenarbeit/rollen">roles</a>, not through group membership.</p></div><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Can ApptiveGrid see our mailboxes or files?</strong> No. The only scopes requested are <code>openid</code>, <code>profile</code>, and <code>email</code>; there is no access through Microsoft Graph.</p><p><strong>Are passwords passed to ApptiveGrid?</strong> No. Sign-in happens entirely at Microsoft. Only the sign-in confirmation and the claims identifying the user are passed on.</p><p><strong>Does the clearance create accounts automatically?</strong> It permits sign-in. An ApptiveGrid account only comes into being once someone actually signs in.</p><p><strong>Does this apply to personal Microsoft accounts too?</strong> No. The restriction only affects work and school accounts belonging to an Entra tenant.</p><p><strong>Ours shows as disabled — did Microsoft do that?</strong> No. <em>Enabled for users to sign-in</em> is set within your own tenant, by a person or by a policy.</p><p><strong>Can we review the clearance later?</strong> Yes. The application then sits under <em>Enterprise applications</em> with every permission granted, and the sign-ins appear in the sign-in log.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/erste-schritte/konto-und-anmeldung">Account and sign-in</a></li><li><a href="/en/erste-schritte/was-ist-apptivegrid">What is ApptiveGrid</a></li><li><a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common Error Messages</a></li></ul>',56)])])}const u=e(a,[["render",r]]);export{g as __pageData,u as default};
